def minIncrementOperations(nums, k):
    n = len(nums)
    if n < 3:
        return 0  # no subarray of length >= 3, already beautiful

    # dp[i] = min cost when index i is raised to k and everything before is covered
    dp = [0] * n
    for i in range(n):
        cost = max(0, k - nums[i])  # cost to raise nums[i] up to k
        if i < 3:
            dp[i] = cost  # the first chosen index may be 0, 1 or 2
        else:
            # previous chosen index is one of i-1, i-2, i-3 (no 3 uncovered in a row)
            dp[i] = cost + min(dp[i - 1], dp[i - 2], dp[i - 3])

    # last chosen index must be among the last three positions
    return min(dp[n - 3], dp[n - 2], dp[n - 1])
